<?php
declare(strict_types=1); defined('ABSPATH') || exit;
trait SN_Future_Superset_Part_2 {
    public static function capture_message_version(object $m,int $editor): int|WP_Error {global $wpdb;$mid=(int)($m->id??0);$c=(int)($m->conversation_id??0);if(!$mid||!$c)return self::error('sn_version_source_invalid','Message revision source is invalid.',500);$plain=SN_Message_Body::decrypt_row($m);if(is_wp_error($plain))return $plain;$rev=1+(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(MAX(revision),0) FROM '.self::versions_table().' WHERE message_id=%d',$mid));$cipher=SN_Communication_Crypto::encrypt($plain,'future-message-version|'.$mid.'|'.$rev);if(is_wp_error($cipher))return $cipher;$ok=$wpdb->insert(self::versions_table(),['message_id'=>$mid,'conversation_id'=>$c,'editor_id'=>$editor,'revision'=>$rev,'body_cipher'=>$cipher,'source_hash'=>hash('sha256',$plain),'created_at'=>self::now()]);return $ok===false?self::db_error():(int)$wpdb->insert_id;}
    public static function message_versions(WP_REST_Request $r): WP_REST_Response|WP_Error {global $wpdb;$mid=absint($r['id']);$m=self::message_row($mid);$u=get_current_user_id();if(!$m||!self::conversation_member((int)$m->conversation_id,$u))return self::not_found();$rows=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::versions_table().' WHERE message_id=%d ORDER BY revision DESC LIMIT 50',$mid));$out=[];foreach(is_array($rows)?$rows:[] as $x){$p=SN_Communication_Crypto::decrypt((string)$x->body_cipher,'future-message-version|'.$mid.'|'.(int)$x->revision);if(!is_wp_error($p))$out[]=['revision'=>(int)$x->revision,'body'=>$p,'editor_id'=>(int)$x->editor_id,'created_at'=>(string)$x->created_at];}return rest_ensure_response(['message_id'=>$mid,'versions'=>$out]);}
    public static function bulk_conversations(WP_REST_Request $r): WP_REST_Response|WP_Error {global $wpdb;$u=get_current_user_id();$ids=array_slice(array_values(array_unique(array_filter(array_map('absint',(array)$r->get_param('conversation_ids'))))),0,100);$act=self::enum((string)$r->get_param('action'),['archive','unarchive','mute','unmute','mark_read'],'');if(!$ids||$act==='')return self::error('sn_bulk_invalid','Select conversations and a supported operation.',400);$n=0;$wpdb->query('START TRANSACTION');try{foreach($ids as $c){if(!self::conversation_member($c,$u))continue;if($act==='mark_read'){$max=(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(MAX(id),0) FROM '.SN_DB::table('messages').' WHERE conversation_id=%d',$c));$ok=$wpdb->query($wpdb->prepare('UPDATE '.SN_DB::table('members').' SET last_read_message_id=GREATEST(last_read_message_id,%d) WHERE conversation_id=%d AND user_id=%d AND left_at IS NULL',$max,$c,$u));}else{$field=str_contains($act,'archive')?'is_archived':'is_muted';$value=in_array($act,['archive','mute'],true)?1:0;$ok=$wpdb->update(SN_DB::table('members'),[$field=>$value],['conversation_id'=>$c,'user_id'=>$u,'left_at'=>null]);}if($ok===false)throw new RuntimeException('bulk');$n++;}$wpdb->query('COMMIT');}catch(Throwable $e){$wpdb->query('ROLLBACK');return self::db_error();}SN_DB::audit('future_bulk_conversations','user',$u,'success',['action'=>$act,'count'=>$n],$u);return rest_ensure_response(['action'=>$act,'changed'=>$n]);}
    public static function save_smart_view(WP_REST_Request $r): WP_REST_Response|WP_Error {$u=get_current_user_id();$name=mb_substr(sanitize_text_field((string)$r->get_param('name')),0,100);if($name==='')return self::error('sn_smart_view_invalid','A view name is required.',400);$criteria=is_array($r->get_param('criteria'))?$r->get_param('criteria'):[];$clean=[];foreach(['unread','muted','archived','has_files','from_verified','conversation_type','days'] as $k)if(array_key_exists($k,$criteria))$clean[$k]=is_bool($criteria[$k])?$criteria[$k]:mb_substr(sanitize_text_field((string)$criteria[$k]),0,60);$id=self::create_record('F17-FUT-11',$u,'user',$u,['name'=>$name,'criteria'=>$clean],self::client($r,$u,'smart-view'),null);return is_wp_error($id)?$id:new WP_REST_Response(['id'=>$id,'name'=>$name,'criteria'=>$clean],201);}
    public static function list_smart_views(): WP_REST_Response {return rest_ensure_response(['items'=>self::owned('F17-FUT-11',get_current_user_id())]);}
    public static function create_qr_invite(WP_REST_Request $r): WP_REST_Response|WP_Error {$space=absint($r->get_param('space_id'));$u=get_current_user_id();if(!self::space_manager($space,$u))return self::error('forbidden','Space management permission is required.',403);$role=self::enum((string)$r->get_param('role'),['member','observer'],'member');$exp=time()+max(1,min(168,absint($r->get_param('expires_in_hours'))?:24))*HOUR_IN_SECONDS;$claims=['typ'=>'f17-space-invite','space_id'=>$space,'role'=>$role,'iss'=>$u,'nonce'=>wp_generate_uuid4(),'exp'=>$exp];$token=SN_Communication_Crypto::sign($claims,'future-space-invite');$hash=hash('sha256',$token);$id=self::create_record('F17-FUT-12',$u,'space',$space,['token_hash'=>$hash,'role'=>$role],'qr-invite:'.$hash,gmdate('Y-m-d H:i:s',$exp));return is_wp_error($id)?$id:new WP_REST_Response(['id'=>$id,'token'=>$token,'expires_at'=>gmdate('c',$exp),'qr_payload'=>'sn-network://community-invite?token='.rawurlencode($token)],201);}
    public static function redeem_qr_invite(WP_REST_Request $r): WP_REST_Response|WP_Error {global $wpdb;$u=get_current_user_id();$token=trim((string)$r->get_param('token'));$claims=SN_Communication_Crypto::verify($token,'future-space-invite');if(is_wp_error($claims)||($claims['typ']??'')!=='f17-space-invite')return self::error('sn_invite_invalid','Invitation is invalid or expired.',403);$space=absint($claims['space_id']??0);$hash=hash('sha256',$token);$client=hash('sha256','qr-invite:'.$hash);$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE feature_id='F17-FUT-12' AND scope_type='space' AND scope_id=%d AND client_key=%s AND state='active' LIMIT 1",$space,$client));if(!$row)return self::error('sn_invite_unavailable','Invitation is no longer available.',410);$d=self::decode($row);if(is_wp_error($d)||!hash_equals((string)($d['token_hash']??''),$hash))return self::error('sn_invite_invalid','Invitation is invalid.',403);$join=self::activate_space_member($space,$u,self::enum((string)($claims['role']??'member'),['member','observer'],'member'),(int)($claims['iss']??0));if(is_wp_error($join))return $join;$wpdb->update(self::records_table(),['state'=>'redeemed','updated_at'=>self::now(),'version'=>(int)$row->version+1],['id'=>(int)$row->id,'state'=>'active','version'=>(int)$row->version]);return rest_ensure_response(['space_id'=>$space,'joined'=>true]);}
    public static function grant_temporary_membership(WP_REST_Request $r): WP_REST_Response|WP_Error {global $wpdb;$space=absint($r->get_param('space_id'));$actor=get_current_user_id();$u=absint($r->get_param('user_id'));if(!self::space_manager($space,$actor))return self::error('forbidden','Space management permission is required.',403);if(!$u||!get_user_by('id',$u)||SN_Policy::is_suspended($u))return self::error('sn_temp_member_invalid','Select an active account.',400);$role=self::enum((string)$r->get_param('role'),['member','observer'],'observer');$until=self::future_time((string)$r->get_param('expires_at'),90*DAY_IN_SECONDS);if(is_wp_error($until))return $until;if(self::space_has_permanent_member($space,$u))return self::error('sn_temp_member_conflict','Account already has permanent membership.',409);$join=self::activate_space_member($space,$u,$role,$actor);if(is_wp_error($join))return $join;$id=self::upsert_record('F17-FUT-13',$u,'space',$space,['user_id'=>$u,'role'=>$role,'granted_by'=>$actor],'temporary:'.$space.':'.$u,$until);return is_wp_error($id)?$id:new WP_REST_Response(['id'=>$id,'space_id'=>$space,'user_id'=>$u,'role'=>$role,'expires_at'=>$until],201);}
    public static function create_mentorship(WP_REST_Request $r): WP_REST_Response|WP_Error {$mentor=get_current_user_id();$student=absint($r->get_param('student_id'));$c=absint($r->get_param('conversation_id'));if(!$student||$student===$mentor||!get_user_by('id',$student)||SN_DB::is_blocked($mentor,$student))return self::error('sn_mentorship_invalid','Select an eligible student.',400);if($c&&(!self::conversation_member($c,$mentor)||!self::conversation_member($c,$student)))return self::error('sn_mentorship_conversation_invalid','Both accounts must be conversation members.',409);if(SN_Policy::age_state($student)!=='adult'&&!(bool)apply_filters('sn_network_guardian_communication_approved',false,$student,$mentor,'mentorship'))return self::error('sn_guardian_approval_required','Guardian approval is required.',403);$id=self::create_record('F17-FUT-14',$mentor,'user',$student,['mentor_id'=>$mentor,'student_id'=>$student,'conversation_id'=>$c,'mode'=>'study'],'mentorship:'.$mentor.':'.$student,null,'pending');return is_wp_error($id)?$id:new WP_REST_Response(['id'=>$id,'status'=>'pending'],201);}
    public static function list_mentorships(): WP_REST_Response {global $wpdb;$u=get_current_user_id();$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE feature_id='F17-FUT-14' AND (owner_id=%d OR scope_id=%d) AND state IN ('pending','active') ORDER BY id DESC LIMIT 100",$u,$u));$out=[];foreach(is_array($rows)?$rows:[] as $x){$d=self::decode($x);if(!is_wp_error($d))$out[]=['id'=>(int)$x->id,'state'=>(string)$x->state,'data'=>$d];}return rest_ensure_response(['items'=>$out]);}
    public static function decide_mentorship(WP_REST_Request $r): WP_REST_Response|WP_Error {global $wpdb;$id=absint($r['id']);$u=get_current_user_id();$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE id=%d AND feature_id='F17-FUT-14' AND scope_id=%d AND state='pending'",$id,$u));if(!$row)return self::not_found();$state=self::enum((string)$r->get_param('decision'),['accept','decline'],'decline')==='accept'?'active':'declined';$ok=$wpdb->update(self::records_table(),['state'=>$state,'updated_at'=>self::now(),'version'=>(int)$row->version+1],['id'=>$id,'version'=>(int)$row->version]);return $ok===1?rest_ensure_response(['id'=>$id,'state'=>$state]):self::error('sn_mentorship_conflict','Mentorship changed before decision.',409);}
    public static function create_citation_card(WP_REST_Request $r): WP_REST_Response|WP_Error {$u=get_current_user_id();$c=absint($r->get_param('conversation_id'));if(!self::conversation_member($c,$u))return self::not_found();$owner=sanitize_key((string)$r->get_param('source_owner'));if(!in_array($owner,['file-06','file-12'],true))return self::error('sn_citation_owner_invalid','Citation must reference File 06 or File 12 canonical truth.',400);$url=esc_url_raw((string)$r->get_param('canonical_url'));if($url!==''&&!self::same_site($url))return self::error('sn_citation_url_invalid','Citation URL must be a canonical same-site URL.',400);$data=['source_owner'=>$owner,'canonical_id'=>mb_substr(sanitize_text_field((string)$r->get_param('canonical_id')),0,191),'canonical_url'=>$url,'title'=>mb_substr(sanitize_text_field((string)$r->get_param('title')),0,300),'locator'=>mb_substr(sanitize_text_field((string)$r->get_param('locator')),0,120)];$id=self::create_record('F17-FUT-15',$u,'conversation',$c,$data,self::client($r,$u,'citation'),null);return is_wp_error($id)?$id:new WP_REST_Response(['id'=>$id,'citation'=>$data],201);}
    public static function create_case_discussion(WP_REST_Request $r): WP_REST_Response|WP_Error {$u=get_current_user_id();$c=absint($r->get_param('conversation_id'));if(!self::conversation_member($c,$u)||!(bool)apply_filters('sn_network_case_discussion_professional_allowed',false,$u,$c))return self::error('sn_case_discussion_forbidden','Professional case-discussion permission is required.',403);$summary=mb_substr(sanitize_textarea_field(wp_unslash((string)$r->get_param('summary'))),0,12000);if($summary===''||self::looks_like_pii($summary))return self::error('sn_case_discussion_pii','Remove names, phone/email, addresses and identity numbers.',400);$data=['summary'=>$summary,'age_band'=>mb_substr(sanitize_text_field((string)$r->get_param('age_band')),0,40),'sex'=>self::enum((string)$r->get_param('sex'),['male','female','unspecified'],'unspecified'),'consent_asserted'=>rest_sanitize_boolean($r->get_param('consent_asserted')),'not_patient_record'=>true];if(!$data['consent_asserted'])return self::error('sn_case_consent_required','Required consent/de-identification assertion is missing.',400);$id=self::create_record('F17-FUT-16',$u,'conversation',$c,$data,self::client($r,$u,'case'),null);return is_wp_error($id)?$id:new WP_REST_Response(['id'=>$id,'case_discussion'=>$data],201);}
